  "Chỉ chủ board và thành viên được thêm trực tiếp mới xem được board này.": "Only the board owner and directly added members can see this board.",
  "Chỉ chủ board và thành viên được thêm trực tiếp mới xem được": "Only the board owner and directly added members can see this",
  "Chỉ chủ dự án và thành viên được thêm mới xem được. Với dự án thuộc khách hàng, người được thêm cũng nhận quyền xem khách hàng (nếu bạn quản lý khách hàng đó). Người theo dõi chỉ xem, nhận thông báo và tự động theo dõi mỗi công việc, công việc con mới của dự án. Người được giao việc, thêm vào thẻ hay theo dõi một công việc của dự án được tự thêm vào đây; đổi quyền của họ tại đây.": "Only the project owner and added members can view it. For a client project, added people also get view access to the client (if you manage that client). Followers have view only access, receive notifications, and automatically follow every new task and subtask in the project. People assigned to, added to a card of, or following a task in the project are added here automatically; change their permissions here.",
  "Chỉ chủ hoặc người quản lý khách hàng được thao tác": "Only the owner or client manager can do this",
  "Chỉ chủ khách hàng, trưởng phòng của chủ và người được thêm mới xem được khách hàng này.": "Only the client's owner, the owner's department head and people who were added can see this client.",
