  "Danh sách trạng thái người dùng chọn được trên trang Công việc, theo thứ tự này. Đổi tên một trạng thái thì mọi công việc đang ở trạng thái đó đổi theo. Hệ thống hiểu ý nghĩa mỗi trạng thái từ tên của nó (cột “Hệ thống hiểu là”) để tính hoàn thành và quá hạn.": "The statuses users can choose on the Tasks page, in this order. Renaming a status also renames it on every task currently in that status. The system understands what each status means from its name (the “System reads it as” column) to work out completion and overdue.",
