  "Máy Mac trả lời nhưng Trình dựng chưa sẵn sàng (thiếu Claude CLI hoặc ffmpeg)": "The Mac responds but Editor is not ready (missing Claude CLI or ffmpeg)",
  "Máy Mac từ chối địa chỉ này: thêm tên miền vào ALLOWED_HOSTS trong .env của máy Mac rồi chạy lại DMI Workspace": "The Mac rejected this address: add the domain to ALLOWED_HOSTS in the Mac's .env, then restart DMI Workspace",
