  "Máy chủ cloud không có ổ đĩa để tạo file sao lưu. Trên máy đã đăng nhập Cloudflare, chạy lệnh dưới đây trong thư mục dự án để xuất toàn bộ database ra": "The cloud server has no disk to create backup files. On a computer signed in to Cloudflare, run the command below in the project folder to export the whole database to",
