  "Máy đọc nội dung và thời lượng từng cảnh, xem bên trong các video source rồi chọn, cắt và xếp clip theo đúng nội dung. Mất khoảng 1–3 phút. Sheet và thư mục source cần chia sẻ cho tài khoản Google đã kết nối.": "The app reads each scene's content and duration, looks inside the source videos, then picks, cuts and arranges clips to match the content. Takes about 1–3 minutes. The sheet and source folder must be shared with the connected Google account.",
