  "Mọi công việc trong phạm vi của bạn. Trang này chỉ đọc (trừ mức ưu tiên); mô tả và kết quả công việc không hiện ở đây.": "All tasks within your scope. This page is read-only (except priority); task descriptions and results aren't shown here.",
