  "Mọi dự án": "All projects",
  "Mọi email thông báo hệ thống gửi (giao việc, cập nhật, thông báo từ Quản trị…) tới người trong phạm vi của bạn.": "Every notification email the system sends (assignments, updates, notifications from Admin…) to people within your scope.",
