  "Mọi người": "Everyone",
  "Mọi nhu cầu": "All needs",
  "Mọi nhân viên đang hoạt động (trừ bạn) sẽ nhận thông báo.": "All active staff (except you) will receive the notification.",
  "Mọi nhân viên đều có vai trò này. Mặc định không có quyền quản trị.": "Every employee has this role. No admin permissions by default.",
  "Mọi nhân viên": "All staff",
  "Mọi nhóm": "All teams",
  "Mọi phân loại": "All classifications",
  "Mọi phòng ban": "All departments",
  "Mọi quyền": "All permissions",
  "Mọi thao tác liên quan tới nhân viên này (giao việc, thêm vào thẻ, board, dự án, khách hàng, bình luận, đổi hạn…) được gửi tới email này.": "Everything that concerns this employee (assigned tasks, being added to cards, boards, projects, clients, comments, due date changes…) is sent to this email.",
  "Mọi thay đổi người dùng làm qua hệ thống (thêm, sửa, xoá, gửi, xuất…), kể cả thao tác bị từ chối vì thiếu quyền.": "Every change users make through the system (add, edit, delete, send, export…), including actions denied for lack of permission.",
  "Mọi thẻ đã xong.": "All cards are done.",
  "Mọi trang, mọi board, Quản trị": "All pages, all boards, Admin",
  "Mọi trạng thái": "All statuses",
  "Mọi tài khoản của công ty đều ở workspace này; thêm người, đổi phòng ban (role) ở trang Quản trị. Quản trị viên xem được mọi board; mỗi phòng chỉ xem board của phòng mình; ai được thêm vào một board thì xem theo quyền được cấp ở board đó.": "All company accounts are in this workspace; add people and change departments (role) on the Admin page. Admins can see every board; each department only sees its own boards; anyone added to a board sees it with the permission granted on that board.",
  "Mọi tình trạng": "All statuses",
  "Mọi vai trò": "All roles",
  "Mọi đối tượng": "All objects",
  "Mỗi công việc tối đa 20 người được giao": "Up to 20 assignees per task",
  "Mỗi dòng một mục; mỗi mục thành một công việc con.": "One item per line; each item becomes a subtask.",
  "Mỗi dòng một ý": "One point per line",
  "Mỗi file tối đa 20.000 dòng bao gồm dòng nhóm và dòng trống": "Up to 20,000 rows per file, including group rows and blank rows",
  "Mỗi file tối đa 20.000 dòng.": "Maximum 20,000 rows per file.",
  "Mỗi lần nhập tối đa 2.000 khách hàng.": "Up to 2,000 clients per import.",
  "Mỗi lần nhập tối đa 5.000 công việc": "Up to 5,000 tasks per import",
  "Mỗi lần nhập tối đa 5.000 công việc.": "Maximum 5,000 tasks per import.",
  "Mỗi lần xem tối đa một năm": "One year maximum per view",
  "Mỗi nhân viên trong kỳ: việc được giao (theo thời hạn), hoàn thành đúng hạn và trễ hạn, việc đang quá hạn, số thao tác.": "Each employee in the period: tasks assigned (by due date), completed on time and late, currently overdue, number of actions.",
  "Mỗi phòng ban có board riêng trong Workspace, các trang công cụ người trong phòng mở được (tab Media Execute gồm Drive và Trình dựng) và các role của phòng. Mỗi role một cấp:": "Each department has its own board in Workspace, the tool pages its people can open (the Media Execute tab includes Drive and Editor) and the department's roles. Each role has one level:",
  "Mỗi phòng ban có board riêng, các trang công cụ người trong phòng mở được và các chức vụ của phòng.": "Each department has its own board, the tool pages people in the department can open, and the department's positions.",
  "Mỗi shot ngắn lại cho nhịp nhanh hơn": "Shorten each shot for a faster pace",
  "Mỗi tab mất khoảng 1–3 phút; các dự án hiện dần trong danh sách bên dưới. Tab bị ẩn trong sheet không được tính.": "Each tab takes about 1–3 minutes; projects appear gradually in the list below. Tabs hidden in the sheet are not counted.",
  "Mỗi vai trò là một tập quyền ở một phạm vi dữ liệu. Cấp của vai trò quyết định ai quản lý được ai: bạn chỉ sửa, gán và thu hồi vai trò thấp hơn vai trò của mình.": "Each role is a set of permissions at a data scope. A role's level decides who can manage whom: you can only edit, assign and revoke roles lower than your own.",
  "Một cảnh liền": "Single continuous shot",
  "Một người có thể giữ nhiều vai trò; quyền cộng lại theo phạm vi rộng nhất. Có thể giới hạn phạm vi của từng vai trò cho từng người.": "One person can hold several roles; permissions add up to the widest scope. Each role's scope can be limited for each person.",
  "Một người không thể là quản lý trực tiếp của chính mình": "A person can't be their own direct manager",
