  "Nhiều model không tự đổi tốc độ chuẩn. Nếu clip ra tốc độ đều, kéo đường cong tốc độ trong CapCut (Speed → Curve): nhanh, chậm ×0.1 khi xe ngang máy quay, rồi nhanh lại đúng nhịp drop.": "Many models don't change speed properly on their own. If the clip comes out at a constant speed, drag the speed curve in CapCut (Speed → Curve): fast, slow ×0.1 as the car passes the camera, then fast again right on the drop.",
