  "Nói Claude cần đổi gì: Claude đọc lại sheet và xem lại các source rồi sửa bản dựng. Outro logo được giữ ở cuối; ⌘/Ctrl+Z để hoàn tác.": "Tell Claude what to change: Claude re-reads the sheet and re-checks the sources, then edits the cut. The logo outro is kept at the end; ⌘/Ctrl+Z to undo.",
