  "Nền động": "Animated background",
  "Nền “Tự động” là gradient theo màu logo: logo vốn nằm trên nền màu thì lấy đúng màu đó; còn lại lấy màu chủ đạo của logo, nhạt sau logo tối và đậm sau logo sáng. Logo chỉ có đen trắng thì dùng nền trắng hoặc đen. Tắt xoá nền thì ảnh gốc được mở rộng cho vừa khung.": "The “Auto” background is a gradient based on the logo's colors: a logo that sits on a colored background uses that exact color; otherwise the logo's dominant color is used, light behind a dark logo and deep behind a light logo. A black-and-white logo uses a white or black background. With background removal off, the original image is extended to fit the frame.",
