  "Phục hồi thay toàn bộ dữ liệu hiện tại của mọi người nên không làm từ giao diện. Cách làm: dừng máy chủ, sao lưu file": "Restoring replaces everyone's current data, so it can't be done from the interface. To restore: stop the server, back up the current",
