  "Prompt (tiếng Anh — sửa thoải mái)": "Prompt (in English — edit freely)",
  "Prompt phân tích (kèm số đo ở trên) được sao chép sẵn. Gemini nhận được cả video; với ChatGPT và Claude, trang sẽ tải về một ảnh gồm các khung hình để bạn đính kèm.": "The analysis prompt (with the measurements above) is already copied. Gemini accepts the whole video; for ChatGPT and Claude, the page downloads an image of the frames for you to attach.",
