  "Quyền được chia theo module. Mỗi quyền tương ứng một kiểm tra trên máy chủ nên danh sách quyền do hệ thống định nghĩa; vai trò chọn quyền nào và ở phạm vi nào.": "Permissions are grouped by module. Each permission matches a check on the server, so the permission list is defined by the system; a role chooses which permissions it has and at which scope.",
