  "Rung máy": "Camera shake",
  "Rê chuột lên ô để xem quyền đó cho phép làm gì. Bạn không cấp được quyền (hay phạm vi) mà chính bạn chưa có. Hệ thống chưa có quy trình duyệt nào nên chưa có quyền “Duyệt”; quyền sẽ được thêm khi có luồng duyệt thật.": "Hover over a cell to see what that permission allows. You can't grant a permission (or scope) you don't have yourself. The system has no approval workflow yet, so there is no “Approve” permission; it will be added when a real approval flow exists.",
