  "Thứ tự các bước một công việc đi qua. Thứ tự này là thứ tự trạng thái trong ô chọn trên trang Công việc. Hệ thống chưa chặn việc nhảy bước: người làm vẫn chọn được trạng thái bất kỳ.": "The order of steps a task goes through. This is also the order of statuses in the dropdown on the Tasks page. The system doesn't block skipping steps yet: assignees can still pick any status.",
