  "Token Meta chưa đọc được tài khoản quảng cáo nào.": "The Meta token can’t read any ad accounts.",
  "Token Meta không hợp lệ hoặc đã hết hạn. Quản trị viên hãy dán token mới trong tab Cài đặt.": "Meta token is invalid or has expired. An admin should paste a new token in the Settings tab.",
  "Token Meta không đọc được tài khoản quảng cáo này": "The Meta token can't read this ad account",
  "Token chưa đọc được caption, headline và liên kết quảng cáo.": "The token can't read ad captions, headlines and links yet.",
  "Token chưa đọc được cấu hình ad set và đối tượng.": "The token can't read ad set and audience settings yet.",
  "Token chỉ được lưu trên máy chủ DMI Workspace, không hiện lại đầy đủ và không gửi tới trình duyệt của người khác. DMI Workspace chỉ đọc số liệu, không sửa quảng cáo.": "The token is stored only on the DMI Workspace server, is never shown in full again, and is never sent to other users' browsers. DMI Workspace only reads data and never edits ads.",
  "Token không có quyền đọc tài khoản quảng cáo này (cần quyền ads_read). {0}": "The token doesn't have permission to read this ad account (ads_read required). {0}",
  "Token không đọc được tài khoản quảng cáo đã chọn": "The token can't read the selected ad account",
  "Token này chưa được cấp tài khoản quảng cáo nào. Trong Business Manager, giao tài khoản quảng cáo cho người dùng hệ thống của token (quyền xem hiệu quả).": "This token has no ad accounts assigned. In Business Manager, assign the ad accounts to the token's system user (view performance permission).",
  "Tool đọc sheet, lấy video theo link và tên file trong cột Source, rồi xếp lên timeline đúng thứ tự từng hàng. Sheet không có video thì tự tạo video chữ chuyển động từ kịch bản. Sheet và thư mục source cần chia sẻ cho tài khoản Google đã kết nối.": "The tool reads the sheet, fetches videos by link and file name in the Source column, then arranges them on the timeline in row order. If the sheet has no videos, it automatically creates a motion-text video from the script. The sheet and source folder must be shared with the connected Google account.",
