  "Từng trường đã đổi của công việc, khách hàng, nhân viên, thẻ, board…: giá trị trước và sau. Mật khẩu, mô tả, kết quả và ghi chú chỉ ghi là “đã đổi”.": "Each changed field of tasks, clients, employees, cards, boards…: the value before and after. Passwords, descriptions, results and notes are only recorded as “changed”.",
  "Tự làm tại nhà": "DIY at home",
  "Tự theo Conversion Type": "Auto by Conversion Type",
  "Tự tìm": "Auto-find",
  "Tự điền các ô trống từ khách hàng, dự án và Meta Ads đã liên kết. Nội dung bạn đã nhập được giữ lại. Cấu hình Ads là cấu hình hiện tại; chi tiêu là số thực tế trong kỳ.": "Auto-fill empty fields from the linked client, project and Meta Ads. Content you’ve entered is kept. Ads settings are the current settings; spend is the actual amount for the period.",
